package ai.taskforge.api; import ai.taskforge.ai.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai") public class AiController { private final LlmProvider mock,openai; private final String provider; public AiController(MockLlmProvider m,OpenAiLlmProvider o,@Value("${taskforge.ai-provider}")String p){mock=m;openai=o;provider=p;} record AnalyzeRequest(@NotBlank @Size(max=30000) String text,String sourceType,String sourceId){} @PostMapping("/analyze") Object analyze(@Valid @RequestBody AnalyzeRequest r){try{return provider.equalsIgnoreCase("openai")?openai.analyze(r.text()):mock.analyze(r.text());}catch(Exception e){throw new ApiException("AI_ANALYSIS_FAILED","AI analysis could not return a valid structured result.");}} }
